File: src/PolyNetworkCrossChain.sol (lines 1-103 of 103)
    1 | // SPDX-License-Identifier: MIT
    2 | pragma solidity ^0.8.24;
    3 | 
    4 | /// @title CrossChainManager + CrossChainData
    5 | /// @notice Minimal reproduction of the real Poly Network EthCrossChainManager/EthCrossChainData
    6 | ///         contracts exploited on Ethereum mainnet, 2021-08-11 (~$611M across ETH/BSC/Polygon,
    7 | ///         the largest DeFi hack at the time; nearly all funds were later voluntarily returned
    8 | ///         by the attacker).
    9 | ///
   10 | /// @dev REAL PROTOCOL CONTEXT
   11 | ///      Poly Network's `EthCrossChainManager` is a privileged relay: it verifies a source-chain
   12 | ///      block header (via consensus-node signatures) and a Merkle proof that a specific
   13 | ///      cross-chain transaction was included in that block, then calls
   14 | ///      `executeCrossChainTx`, which invokes the DESTINATION-side target contract named inside
   15 | ///      the proven message. This reproduction keeps that real function name
   16 | ///      (`verifyHeaderAndExecuteTx`) and its real consequence (an arbitrary external call to a
   17 | ///      caller-named target using caller-named calldata) while replacing the actual BLS/multi-
   18 | ///      signature consensus-header verification and Merkle-inclusion proof with a stand-in
   19 | ///      `_verifyProof` -- that machinery is extensive and genuinely sound in the real protocol;
   20 | ///      it is NOT where the bug lived, so reproducing it in full would only obscure the actual
   21 | ///      vulnerability.
   22 | ///
   23 | ///      Per the real post-mortem: "Poly checks that the target is a contract, but they forgot
   24 | ///      to prevent users from calling [Poly's own] EthCrossChainData contract... tricking
   25 | ///      EthCrossChainManager into calling EthCrossChainData, passing the onlyOwner check"
   26 | ///      (because `msg.sender` for that internal call IS EthCrossChainManager itself, which
   27 | ///      genuinely is EthCrossChainData's configured owner) "...to trigger the function that
   28 | ///      changes the public keys" -- i.e. the consensus key Poly itself trusts to verify ALL
   29 | ///      FUTURE cross-chain messages. This reproduction implements that exact chain: the manager
   30 | ///      never excludes its own trusted config contract from the set of callable targets.
   31 | contract CrossChainData {
   32 |     address public owner;
   33 |     bytes public currentEpochConsensusPubKey;
   34 | 
   35 |     event ConsensusKeyChanged(bytes newKey);
   36 | 
   37 |     constructor(address _owner) {
   38 |         owner = _owner;
   39 |     }
   40 | 
   41 |     modifier onlyOwner() {
   42 |         require(msg.sender == owner, "not owner");
   43 |         _;
   44 |     }
   45 | 
   46 |     /// @dev Standard ownership transfer, used once during deployment wiring to hand control to
   47 |     ///      the CrossChainManager (see the constructor-cycle note in the test's setUp()).
   48 |     function transferOwnership(address newOwner) external onlyOwner {
   49 |         owner = newOwner;
   50 |     }
   51 | 
   52 |     /// @notice Sets the consensus public key that ALL future cross-chain header verifications
   53 |     ///         will trust. Correctly restricted to `owner` -- which, in the real deployment (and
   54 |     ///         this reproduction), is the CrossChainManager contract itself.
   55 |     function putCurEpochConPubKeyBytes(bytes calldata newKey) external onlyOwner returns (bool) {
   56 |         currentEpochConsensusPubKey = newKey;
   57 |         emit ConsensusKeyChanged(newKey);
   58 |         return true;
   59 |     }
   60 | 
   61 |     function getCurEpochConPubKeyBytes() external view returns (bytes memory) {
   62 |         return currentEpochConsensusPubKey;
   63 |     }
   64 | }
   65 | 
   66 | contract CrossChainManager {
   67 |     CrossChainData public immutable dataContract;
   68 | 
   69 |     constructor(CrossChainData _dataContract) {
   70 |         dataContract = _dataContract;
   71 |     }
   72 | 
   73 |     /// @notice Normal flow: a genuinely proven cross-chain message calls a DeFi-side contract
   74 |     ///         (e.g. a lock/release proxy) to release funds to the message's named recipient.
   75 |     ///
   76 |     /// @dev THE REAL VULNERABLE LOGIC (1:1 with the incident): `toContract` is read directly
   77 |     ///      from the (proven) message and called with no restriction on which address it may
   78 |     ///      be -- including the manager's OWN `dataContract`. Since `msg.sender` during that
   79 |     ///      call is this manager contract, and this manager IS `dataContract.owner()`, ANY
   80 |     ///      function gated by `onlyOwner` on `dataContract` becomes reachable through a
   81 |     ///      sufficiently crafted cross-chain message.
   82 |     function verifyHeaderAndExecuteTx(address toContract, bytes calldata method, bytes calldata args, bytes calldata proof)
   83 |         external
   84 |         returns (bool)
   85 |     {
   86 |         require(_verifyProof(proof), "invalid header/merkle proof");
   87 | 
   88 |         // =====================================================================================
   89 |         // VULNERABLE: no `require(toContract != address(dataContract))` (or, more generally, no
   90 |         // allowlist of legitimate destination-side targets) anywhere before this call.
   91 |         // =====================================================================================
   92 |         (bool ok,) = toContract.call(abi.encodePacked(bytes4(keccak256(bytes(method))), args));
   93 |         require(ok, "cross-chain execution failed");
   94 |         return true;
   95 |     }
   96 | 
   97 |     /// @dev Stand-in for Poly's real consensus-signature + Merkle-inclusion verification. That
   98 |     ///      machinery is not the vulnerability -- this simplification exists so the challenge
   99 |     ///      can focus entirely on the actual bug (the unrestricted `toContract.call` above).
  100 |     function _verifyProof(bytes calldata proof) internal pure returns (bool) {
  101 |         return proof.length > 0;
  102 |     }
  103 | }
